<?php require __DIR__.'/../../app/core/bootstrap.php';$u=require_admin();if(is_post()){csrf_check();$rid=$pdo->query("SELECT id FROM roles WHERE name='pengguna'")->fetchColumn();$st=$pdo->prepare('INSERT INTO users(role_id,nim,name,email,class_name,study_program,faculty,semester,password_hash) VALUES(?,?,?,?,?,?,?,?,?)');try{$st->execute([$rid,trim($_POST['nim']),trim($_POST['name']),trim($_POST['email']),trim($_POST['class_name']),trim($_POST['study_program']),trim($_POST['faculty']),($_POST['semester']??1),password_hash($_POST['password'],PASSWORD_DEFAULT)]);log_activity($pdo,$u['id'],'admin','Tambah pengguna','Membuat pengguna '.$_POST['nim']);flash('success','Pengguna berhasil dibuat.');redirect('/admin/users/index.php');}catch(Throwable $e){$error='NIM/email mungkin sudah terdaftar.';}}require __DIR__.'/../../app/helpers/layout.php';render_start('Tambah Pengguna','Membuat akun mahasiswa',$u);dashboard_nav('admin');render_mid('Tambah Pengguna','Form akun mahasiswa',$u);?><div class="card"><form method="post"><?=csrf_input()?><div class="form-grid"><div class="form-group"><label>NIM</label><input class="input" name="nim" required></div><div class="form-group"><label>Nama</label><input class="input" name="name" required></div><div class="form-group"><label>Email</label><input class="input" type="email" name="email" required></div><div class="form-group"><label>Kelas</label><input class="input" name="class_name"></div><div class="form-group"><label>Program Studi</label><input class="input" name="study_program"></div><div class="form-group"><label>Fakultas</label><input class="input" name="faculty"></div><div class="form-group"><label>Semester</label><input class="input" type="number" min="1" max="14" name="semester" value="1"></div><div class="form-group"><label>Password</label><input class="input" type="password" name="password" required minlength="8"></div></div><button class="btn btn-primary" style="margin-top:18px">Simpan</button><a href="/admin/users/index.php